// Wave A, batch 1: Point of Sale & Retail cluster (13 articles).
//
// See lib/academy-i18n/README.md for the on-disk contract. This file is
// merged into ./index.ts's `translations` export, not imported directly by
// the loader.
//
// GLOSSARY (so) — established by this batch, the first so translation batch
// for Academy content. Reuse these terms verbatim in every later so batch.
// LOCKED terms (from prior AskBiz Somali work, reused exactly, do not vary):
//   faa'iido = profit            dakhli = revenue
//   kayd = stock/inventory       kharashaad = expenses
//   deyn = debt/credit           hadhaaga / baaqi = balance
//   saadaal = forecast           canshuur = tax
//   keeshiye = cashier           maareeye = manager
//   milkiile = owner             dukaan = shop
//   macmiil = customer           Kaydi = Save
//   Jooji = Cancel                Tirtir = Delete
//
// NEW terms established this batch (cross-checked against live so/*.json
// strings already shipped in the product, e.g. locales/so/pos_retail.json,
// locales/so/pos_setup.json, locales/so/landing.json, so kept consistent
// with what a Somali-speaking AskBiz user already sees in the app):
//   POS = POS (kept untranslated, matches locales/so/nav.json "pos": "POS";
//        glossed once per article as "nidaamka POS (meesha iibka)" on first
//        mention where natural)
//   receipt = rasiid                    transaction = macaamil-dhaqaaleed
//   refund = celin lacag / soo-celin lacageed
//   staff = shaqaale                    role = door
//   cart (POS basket) = dambiil         discount = qiimo-dhimis
//   barcode = barcode (kept, matches locales/so/compare.json, landing.json)
//   QR code = koodhka QR
//   void (verb/noun) = baabi'i / baabi'inta (a transaction annulment,
//        distinct from Jooji=Cancel which is used for an in-progress action)
//   audit trail = diiwaanka hubinta (matches locales/so/landing.json)
//   reorder point = heerka dib-u-dalabka   reorder (verb) = dib u dalbo
//   checkout / process a sale = xisaabinta iibka, iibka fulinta
//   payment method = habka lacag-bixinta   cash = lacag caddaan
//   card (payment) = kaadh                sale = iib
//   stockout = kayd la'aan / kaydka oo dhammaaday
//   sales velocity / sell-through rate = xawaaraha iibka
//   dead stock = kayd dhimatay (matches landing.json "Digniinta Kaydka Dhimatay")
//   restock (verb) = dib u buuxi kaydka    receive stock = hel kayd
//   alert / notification = digniin / ogeysiis (used interchangeably; digniin
//        preferred for stock-level warnings to match shipped POS copy)
//   magic link = xiriir hal-mar ah (isticmaalka hal-mar) — glossed on first
//        mention, not left as an English loanword (no established English
//        loanword precedent for this term in shipped so/*.json)
//   small business (owner) = ganacsi yar (ganacsatada ganacsiga yar)
//   margin = faa'iido (kala duwanaanshaha qiimaha iyo kharashka, glossed on
//        first mention where the English distinguishes margin from profit)
//   permission(s) = oggolaansho / awood gelitaan
//   inventory management = maareynta kaydka
//
// Product/proper nouns kept in English throughout: AskBiz, AskBiz POS,
// WhatsApp, role labels (Owner, Manager, Cashier — glossed with the locked
// Somali terms milkiile/maareeye/keeshiye on first mention, English label
// kept alongside as in shipped copy patterns), and literal UI button/section
// names as they appear capitalized in the English source (Add Staff, Invite,
// POS Settings, Refund, Void, Add Note, Receive Stock, Discount [as a tap
// target], Pay, Notes, Transactions, Inventory).
// Official UK legal/institutional names are also left untranslated: HMRC,
// Consumer Rights Act 2015, Making Tax Digital, UK Finance, GDPR.
// Numbers, currency figures (£), and percentages preserved exactly as in the
// English source (this is UK-market source content); Somali does not use a
// different digit/decimal convention for these so no reformatting is applied.

